// Package fakecli is the one fake command-line tool of the test suites
// (OC-02, DEVDESK-797). A test names the tools it wants (docker, podman, kind,
// kubectl, trivy, ...) and the exchanges they answer; the code under test then
// starts them by name through PATH, exactly as it starts the real ones.
//
// The fake is the test binary itself. Install links the test binary under each
// tool name in a directory that becomes the whole PATH; when the binary is
// started under one of those names, Main (or AsTool) answers from the declared
// exchanges instead of running the tests. Every run is appended to a journal the
// test reads back with (*Fake).Invocations. The mode is strict: an argv no
// exchange covers is reported on the tool's stderr, exits non-zero, and fails
// the test when it ends, with the argv received.
//
// Install changes PATH and the process environment through t.Setenv, so it does
// not combine with t.Parallel. This package imports "testing": it belongs to
// _test.go files only, which TestFakeCLIGuardWalk enforces (rule F1).
package fakecli

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"
)

const (
	// envState names the directory holding the scenario and the journal; it is
	// set for the processes the code under test starts.
	envState = "FAKECLI_STATE"
	// envTools lists the tool names the test binary answers to, separated by
	// the path list separator, so a process that merely shares the environment
	// (the test binary re-executed under another name) is not taken for a tool.
	envTools = "FAKECLI_TOOLS"

	scenarioFile = "scenario.json"
	journalFile  = "journal.jsonl"

	// unmatchedExit is what a tool exits with when no exchange covers its argv.
	unmatchedExit = 127
)

// Reply is what a fake tool does for one exchange.
type Reply struct {
	Stdout string
	Stderr string
	Exit   int
}

// Exchange declares the reply to one invocation. Tool restricts it to one tool
// (empty: any installed tool). Args is compared element by element, never as a
// joined string. With Prefix, Args only has to start the argv, so an empty
// Args with Prefix is a catch-all. Among the exchanges that cover an argv an
// exact one wins over a prefix, the longest prefix wins over a shorter one, and
// the first declared wins a tie.
type Exchange struct {
	Tool   string
	Args   []string
	Prefix bool
	Reply  Reply
}

// Source supplies the exchanges a fake answers. Scenario is the usual one;
// anything else that can list exchanges (a recorded fixture replay, OC-08)
// plugs in here without a change to this package.
type Source interface {
	Exchanges() []Exchange
}

// Scenario is a Source made of a literal list of exchanges.
type Scenario []Exchange

// Exchanges returns the list itself.
func (s Scenario) Exchanges() []Exchange { return s }

// Invocation is one run of a fake tool, as journaled.
type Invocation struct {
	Tool string
	// Args is the argv without the tool name.
	Args []string
	// Env is the environment the tool was started with.
	Env []string
	// Matched is false when no exchange covered the argv.
	Matched bool
}

// Fake is the handle Install returns.
type Fake struct {
	dir   string
	state string
}

// Dir is the directory holding the tools, which is the whole of PATH while the
// test runs. It is the directory an engine guard is told to accept.
func (f *Fake) Dir() string { return f.dir }

// Invocations returns the journal, oldest first. It is safe to call while the
// tools are still being started by other goroutines of the code under test.
func (f *Fake) Invocations() []Invocation {
	file, err := os.Open(filepath.Join(f.state, journalFile))
	if err != nil {
		return nil
	}
	defer func() { _ = file.Close() }()

	var out []Invocation
	reader := bufio.NewReader(file)
	for {
		line, err := reader.ReadBytes('\n')
		if len(line) > 0 && line[len(line)-1] == '\n' {
			var inv Invocation
			if json.Unmarshal(line, &inv) == nil {
				out = append(out, inv)
			}
		}
		if err != nil {
			return out
		}
	}
}

// Install puts the named tools alone on PATH and makes them answer src. The
// journal and the scenario live in a directory of their own under t.TempDir.
// When the test ends, every argv no exchange covered fails it.
func Install(t testing.TB, src Source, tools ...string) *Fake {
	t.Helper()

	dir, state := t.TempDir(), t.TempDir()

	var exchanges []Exchange
	if src != nil {
		exchanges = src.Exchanges()
	}
	body, err := json.Marshal(exchanges)
	if err != nil {
		t.Fatalf("fakecli: encoding the scenario: %v", err)
	}
	if err := os.WriteFile(filepath.Join(state, scenarioFile), body, 0o600); err != nil {
		t.Fatalf("fakecli: writing the scenario: %v", err)
	}

	self, err := os.Executable()
	if err != nil {
		t.Fatalf("fakecli: locating the test binary: %v", err)
	}
	for _, name := range tools {
		if err := link(self, filepath.Join(dir, toolFile(name))); err != nil {
			t.Fatalf("fakecli: installing %s: %v", name, err)
		}
	}

	t.Setenv("PATH", dir)
	t.Setenv(envState, state)
	t.Setenv(envTools, strings.Join(tools, string(os.PathListSeparator)))

	f := &Fake{dir: dir, state: state}
	t.Cleanup(func() {
		for _, inv := range f.Invocations() {
			if !inv.Matched {
				t.Errorf("fakecli: no exchange declared for %s %q", inv.Tool, inv.Args)
			}
		}
	})
	return f
}

// InstallAt links one more tool, outside PATH, at dir/name and returns its path:
// the situation of a binary the configuration names by its path. The tool
// answers the scenario of f like the ones on PATH.
func (f *Fake) InstallAt(t testing.TB, dir, name string) string {
	t.Helper()
	self, err := os.Executable()
	if err != nil {
		t.Fatalf("fakecli: locating the test binary: %v", err)
	}
	path := filepath.Join(dir, toolFile(name))
	if err := link(self, path); err != nil {
		t.Fatalf("fakecli: installing %s: %v", path, err)
	}
	t.Setenv(envTools, os.Getenv(envTools)+string(os.PathListSeparator)+name)
	return path
}

// toolFile is the file name a tool is installed under.
func toolFile(name string) string {
	if runtime.GOOS == "windows" {
		return name + ".exe"
	}
	return name
}

// link makes path start the test binary: a symbolic link where there is one, a
// copy where there is not (Windows, or a file system that refuses links).
func link(self, path string) error {
	if runtime.GOOS != "windows" {
		if err := os.Symlink(self, path); err == nil {
			return nil
		}
	}
	src, err := os.Open(self)
	if err != nil {
		return err
	}
	defer func() { _ = src.Close() }()
	dst, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o755)
	if err != nil {
		return err
	}
	if _, err := io.Copy(dst, src); err != nil {
		_ = dst.Close()
		return err
	}
	return dst.Close()
}

// Main is what a TestMain calls: it answers as the tool when the test binary
// was started under a name Install gave it, and runs the tests otherwise.
//
//	func TestMain(m *testing.M) { os.Exit(fakecli.Main(m)) }
//
// A TestMain that prepares state before m.Run (a temporary HOME, say) calls
// AsTool first, so a tool process neither creates nor deletes it.
func Main(m *testing.M) int {
	if code, ok := AsTool(); ok {
		return code
	}
	return m.Run()
}

// AsTool serves one invocation when the process was started as an installed
// tool, and returns its exit code with true. Otherwise it does nothing.
func AsTool() (int, bool) {
	state, tools := os.Getenv(envState), os.Getenv(envTools)
	if state == "" || tools == "" {
		return 0, false
	}
	name := strings.TrimSuffix(filepath.Base(os.Args[0]), ".exe")
	if !slices.Contains(filepath.SplitList(tools), name) {
		return 0, false
	}
	return serve(state, name, os.Args[1:]), true
}

// serve is the whole of a fake tool. It runs in its own process, so it reports
// through its exit code and streams rather than through testing.T.
func serve(state, tool string, argv []string) int {
	raw, err := os.ReadFile(filepath.Join(state, scenarioFile))
	if err != nil {
		_, _ = fmt.Fprintf(os.Stderr, "fakecli: unreadable scenario: %v\n", err)
		return unmatchedExit
	}
	var exchanges []Exchange
	if err := json.Unmarshal(raw, &exchanges); err != nil {
		_, _ = fmt.Fprintf(os.Stderr, "fakecli: unreadable scenario: %v\n", err)
		return unmatchedExit
	}

	chosen := pick(exchanges, tool, argv)
	if err := journal(state, Invocation{Tool: tool, Args: argv, Env: os.Environ(), Matched: chosen != nil}); err != nil {
		_, _ = fmt.Fprintf(os.Stderr, "fakecli: cannot journal the invocation: %v\n", err)
		return unmatchedExit
	}
	if chosen == nil {
		_, _ = fmt.Fprintf(os.Stderr, "fakecli: no exchange declared for %s %q\n", tool, argv)
		return unmatchedExit
	}

	_, _ = fmt.Fprint(os.Stdout, chosen.Reply.Stdout)
	_, _ = fmt.Fprint(os.Stderr, chosen.Reply.Stderr)
	return chosen.Reply.Exit
}

// pick returns the exchange answering the argv, or nil.
func pick(exchanges []Exchange, tool string, argv []string) *Exchange {
	var best *Exchange
	for i := range exchanges {
		e := &exchanges[i]
		if e.Tool != "" && e.Tool != tool {
			continue
		}
		switch {
		case !e.Prefix && slices.Equal(e.Args, argv):
			return e
		case e.Prefix && len(e.Args) <= len(argv) && slices.Equal(e.Args, argv[:len(e.Args)]):
			if best == nil || len(e.Args) > len(best.Args) {
				best = e
			}
		}
	}
	return best
}

// journal appends one entry with a single write, so concurrent tools never
// interleave inside a line.
func journal(state string, inv Invocation) error {
	line, err := json.Marshal(inv)
	if err != nil {
		return err
	}
	file, err := os.OpenFile(filepath.Join(state, journalFile), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	if _, err := file.Write(append(line, '\n')); err != nil {
		_ = file.Close()
		return err
	}
	return file.Close()
}

package fakecli_test

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// OC-02 (DEVDESK-797): the static guard that keeps the fake binary single and
// out of production. Modelled on the host store guard
// (internal/credentials/hoststore_guard_test.go): it reads every .go file of
// the module with go/parser, no type information, and reports two rules.
//
//	F1  an import of internal/testutil/fakecli from a non-test file (it imports
//	    "testing" and must not reach a production binary). No exception, like K3.
//	F2  a _test.go file that puts its own fake binary on PATH: it overrides PATH
//	    (Setenv("PATH", ...)) and either copies the test binary (os.Executable)
//	    or writes a script (a string literal starting with "#!"). Such a fake
//	    belongs to fakecli. The only exceptions are the files of legacyFakes,
//	    which must shrink and never grow.
//
// What the guard cannot see: a fake whose PATH is set through os/exec's
// Cmd.Env or through a helper in another package, an import path built at run
// time, a shim written without a "#!" literal or without os.Executable.

const (
	ruleFakeCLIInProd = "F1"
	ruleOwnFakeOnPath = "F2"

	fakeCLIPath      = "github.com/anthnel/devdesk/internal/testutil/fakecli"
	fakeCLIDir       = "internal/testutil/fakecli"
	fakeGuardMinimum = 50
)

// fakeGuardExcludedDirs are skipped at any depth below the module root, like the
// other source guards.
var fakeGuardExcludedDirs = []string{".worktrees", ".git", "vendor", "testdata", "docs-site", "node_modules"}

// legacyFakes lists the test files that still carry their own fake binary on
// PATH. The list only shrinks: the guard fails when an entry no longer matches
// (migrate it and delete the line) and when a new file is added to the tree.
//
//   - Temporary, tracked for later stories:
//     nexusbench/helper_process_test.go is deferred (OC-02 follow-up): a
//     development tool outside dk (the story allows it), and its fakes need
//     what fakecli does not offer yet (a hang, a large stdout, the content of
//     --authfile and --policy files, the PID, TMPDIR, stdin).
//     nexusbench/kubectl_test.go (records argv and stdin) goes with it.
//     app/scan_tools_hermetic_test.go (witness scripts for trivy, gitleaks and
//     plumber) is followed up with OC-03b.
//   - Permanent, assumed: browser and clipboard stand in for programs that are
//     not engine tools (a browser opener, powershell).
var legacyFakes = map[string]string{
	"internal/nexusbench/helper_process_test.go": "temporary, OC-02 follow-up: hang, large stdout, authfile and policy capture, PID, TMPDIR, stdin",
	"internal/nexusbench/kubectl_test.go":        "temporary, OC-02 follow-up: kubectl script that records argv and stdin",
	"internal/app/scan_tools_hermetic_test.go":   "temporary, tracked with OC-03b: witness scripts for trivy, gitleaks and plumber",
	"internal/browser/browser_test.go":           "permanent: browser opener, not an engine tool",
	"internal/clipboard/clipboard_test.go":       "permanent: powershell stand-in, not an engine tool",
}

// fakeViolation is one place where the fake binary rules are broken.
type fakeViolation struct {
	File string // slash path from the module root
	Line int
	Rule string // "F1" or "F2"
}

// fakeAdvice names the rule broken and the way out.
var fakeAdvice = map[string]string{
	ruleFakeCLIInProd: "imports internal/testutil/fakecli from a non-test file; " +
		"it imports \"testing\" and belongs to _test.go files only (OC-02, DEVDESK-797)",
	ruleOwnFakeOnPath: "puts its own fake binary on PATH; install one with fakecli.Install(t, scenario, tools...) " +
		"instead (OC-02, DEVDESK-797)",
}

func (v fakeViolation) String() string {
	return fmt.Sprintf("%s:%d: %s %s", v.File, v.Line, v.Rule, fakeAdvice[v.Rule])
}

// scanFakeSource parses src as the file name (a slash path from the module
// root) and returns its violations ordered by line, then rule.
func scanFakeSource(name string, src []byte) ([]fakeViolation, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	isTest := strings.HasSuffix(name, "_test.go")

	var out []fakeViolation
	add := func(pos token.Pos, rule string) {
		out = append(out, fakeViolation{File: name, Line: fset.Position(pos).Line, Rule: rule})
	}

	for _, spec := range f.Imports {
		p, err := strconv.Unquote(spec.Path.Value)
		if err != nil {
			continue
		}
		if p == fakeCLIPath && !isTest {
			add(spec.Pos(), ruleFakeCLIInProd)
		}
	}

	if isTest && path.Dir(name) != fakeCLIDir {
		var pathOverride bool
		var firstBody token.Pos
		ast.Inspect(f, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.CallExpr:
				sel, ok := n.Fun.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				if sel.Sel.Name == "Setenv" && len(n.Args) > 0 && isStringLit(n.Args[0], "PATH") {
					pathOverride = true
				}
				if sel.Sel.Name == "Executable" && len(n.Args) == 0 {
					if id, ok := sel.X.(*ast.Ident); ok && id.Name == "os" && !firstBody.IsValid() {
						firstBody = n.Pos()
					}
				}
			case *ast.BasicLit:
				if n.Kind == token.STRING {
					if s, err := strconv.Unquote(n.Value); err == nil && strings.HasPrefix(s, "#!") && !firstBody.IsValid() {
						firstBody = n.Pos()
					}
				}
			}
			return true
		})
		if pathOverride && firstBody.IsValid() {
			add(firstBody, ruleOwnFakeOnPath)
		}
	}

	slices.SortStableFunc(out, func(a, b fakeViolation) int {
		if a.Line != b.Line {
			return a.Line - b.Line
		}
		return strings.Compare(a.Rule, b.Rule)
	})
	return out, nil
}

// isStringLit tells whether e is the string literal want.
func isStringLit(e ast.Expr, want string) bool {
	lit, ok := e.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return false
	}
	s, err := strconv.Unquote(lit.Value)
	return err == nil && s == want
}

// scanFakeTree scans every .go file under root and returns the violations and
// the number of files read.
func scanFakeTree(root string) ([]fakeViolation, int, error) {
	var all []fakeViolation
	files := 0
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if d.IsDir() {
			if rel != "." && slices.Contains(fakeGuardExcludedDirs, d.Name()) {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(rel, ".go") {
			return nil
		}
		src, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		vs, err := scanFakeSource(rel, src)
		if err != nil {
			return fmt.Errorf("%s: %w", rel, err)
		}
		files++
		all = append(all, vs...)
		return nil
	})
	return all, files, err
}

// fakeModuleRoot walks up from dir to the directory holding go.mod.
func fakeModuleRoot(dir string) (string, error) {
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("no go.mod above %s", dir)
		}
		dir = parent
	}
}

var (
	fakeGuardOnce       sync.Once
	fakeGuardViolations []fakeViolation
	fakeGuardFiles      int
	fakeGuardErr        error
)

// scanFakeRepo scans the module that holds this package, once per test process.
func scanFakeRepo(t *testing.T) []fakeViolation {
	t.Helper()
	fakeGuardOnce.Do(func() {
		wd, err := os.Getwd()
		if err != nil {
			fakeGuardErr = err
			return
		}
		root, err := fakeModuleRoot(wd)
		if err != nil {
			fakeGuardErr = err
			return
		}
		fakeGuardViolations, fakeGuardFiles, fakeGuardErr = scanFakeTree(root)
	})
	if fakeGuardErr != nil {
		t.Fatalf("scanning the module for fake binaries: %v", fakeGuardErr)
	}
	// A walk that reads almost nothing would pass for the wrong reason.
	if fakeGuardFiles < fakeGuardMinimum {
		t.Fatalf("the fake binary guard read %d files, want the whole module", fakeGuardFiles)
	}
	return fakeGuardViolations
}

// Criterion 4 on the real module: nothing outside a _test.go file imports
// fakecli. Criterion 3 on the real module: no test file but the files of
// legacyFakes puts a fake of its own on PATH; oci_resources/faketool_test.go and
// scan/dependencies_test.go, named by the story, are not in that list
// (nexusbench/helper_process_test.go is, deferred).
func TestFakeCLIGuardWalk(t *testing.T) {
	for _, v := range scanFakeRepo(t) {
		if v.Rule == ruleOwnFakeOnPath {
			if _, ok := legacyFakes[v.File]; ok {
				continue
			}
		}
		t.Error(v.String())
	}
}

// An exception that no longer matches is dead weight: the list only shrinks.
func TestLegacyFakesAreStillFakes(t *testing.T) {
	flagged := map[string]bool{}
	for _, v := range scanFakeRepo(t) {
		if v.Rule == ruleOwnFakeOnPath {
			flagged[v.File] = true
		}
	}
	for file := range legacyFakes {
		if !flagged[file] {
			t.Errorf("%s is listed in legacyFakes but no longer carries its own fake binary: delete the line", file)
		}
	}
}

// fakeGuardCase is one synthetic source and the violations expected, each as
// "line rule".
type fakeGuardCase struct {
	name string
	file string
	src  string
