			src: `package fakecliextra
import ("os";"testing")
func install(t *testing.T) {
	_, _ = os.Executable()
	t.Setenv("PATH", t.TempDir())
}
`,
			want: []string{"4 F2"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			vs, err := scanFakeSource(tc.file, []byte(tc.src))
			if err != nil {
				t.Fatalf("scanFakeSource: %v", err)
			}
			var got []string
			for _, v := range vs {
